import type React from 'react';

interface CustomButtonProps {
  children: React.ReactNode;
  variant?: 'filled' | 'outlined' | 'canceled';
  onClick?: () => void;
  className?: string;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
}

export function CustomButton({
  children,
  variant = 'filled',
  onClick,
  className = '',
  disabled = false,
  type = 'button',
}: CustomButtonProps) {
  const baseClasses =
    'px-8 py-4 rounded-lg font-semibold text-lg transition-all duration-300 ease-in-out outline-none border-2';

  const variantClasses = {
    filled: `bg-primary text-black border-green-400 hover:bg-primary hover:border-primary active:bg-primary-pressed active:border-primary-pressed ${
      disabled ? 'cursor-not-allowed bg-primary-disabled' : 'cursor-pointer'
    }`,
    outlined: `bg-transparent text-primary border-primary hover:bg-primary-hover hover:text-black active:bg-primary active:text-black ${
      disabled ? 'cursor-not-allowed' : 'cursor-pointer'
    }`,
    canceled: `bg-card-cancel text-primary border-card-cancel hover:bg-card-cancel-hover hover:text-black active:bg-card-cancel-active active:text-black ${
      disabled ? 'cursor-not-allowed' : 'cursor-pointer'
    }`,
  };

  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      className={`${baseClasses} ${variantClasses[variant]} ${className}`}
    >
      {children}
    </button>
  );
}

'use client';

import type { HTMLAttributes } from 'react';

interface CustomCheckboxProps extends HTMLAttributes<HTMLDivElement> {
  checked: boolean;
  onToggle: () => void;
}

export function CustomCheckbox({
  checked,
  onToggle,
  className,
  ...props
}: CustomCheckboxProps) {
  return (
    <div
      role="checkbox"
      aria-checked={checked}
      tabIndex={0}
      onClick={onToggle}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onToggle();
        }
      }}
      className={`w-8 h-8 rounded-lg border-2 cursor-pointer flex items-center justify-center
        ${
          checked
            ? 'bg-primary border-primary'
            : 'bg-transparent border-gray-500'
        }
        transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2 focus:ring-offset-gray-900
        ${className || ''}`}
      {...props}
    >
      <span className="sr-only">{checked ? 'Checked' : 'Unchecked'}</span>

      {checked && (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          className="w-5 h-5 text-white"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          strokeWidth={3}
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            d="M5 13l4 4L19 7"
          />
        </svg>
      )}
    </div>
  );
}

