name: Deploy to Dev Environment
on:
  push:
    branches: [ "develop" ]

jobs:
  build:
    name: Build docker image
    runs-on: develop-runner
    steps:
      - name: Checkout
        uses: actions/checkout@v6
      - name: Build Docker image
        run: docker build --no-cache -f ./deployment/Dockerfile -t infra-backend:dev .
      - name: Check migration tool
        run: |
          which migrate || (echo "migrate tool not found, installing..." && \
          curl -L https://github.com/golang-migrate/migrate/releases/download/v4.19.1/migrate.linux-amd64.tar.gz | tar xvz && \
          sudo mv migrate /usr/local/bin/migrate)
      - name: Run database migrations
        env:
          INFRA_POSTGRES_DATABASE: ${{ secrets.DEV_POSTGRES_DATABASE }}
          INFRA_POSTGRES_USERNAME: ${{ secrets.DEV_POSTGRES_USER }}
          INFRA_POSTGRES_PASSWORD: ${{ secrets.DEV_POSTGRES_PASSWORD }}
        run: |
          DATABASE_URL="postgres://${INFRA_POSTGRES_USERNAME}:${INFRA_POSTGRES_PASSWORD}@localhost:5432/${INFRA_POSTGRES_DATABASE}?sslmode=disable&timezone=UTC" make migration-up
  deploy:
    name: Deploy to Development Server
    runs-on: develop-runner
    needs: build
    steps:
      - name: Deploy with Docker Compose
        env:
          INFRA_ENVIRONMENT: development
          INFRA_POSTGRES_USERNAME: ${{ secrets.DEV_POSTGRES_USER }}
          INFRA_POSTGRES_DATABASE: ${{ secrets.DEV_POSTGRES_DATABASE }}
          INFRA_POSTGRES_PASSWORD: ${{ secrets.DEV_POSTGRES_PASSWORD }}

          INFRA_REST_RECAPTCHA_GOOGLE_SECRET: ${{ secrets.GOOGLE_RECAPTCHA_SECRET }}

          INFRA_CONTACT_FORM_SMTP_HOST: ${{ vars.INFRA_CONTACT_FORM_SMTP_HOST }}
          INFRA_CONTACT_FORM_SMTP_PORT: ${{ vars.INFRA_CONTACT_FORM_SMTP_PORT }}
          INFRA_CONTACT_FORM_SMTP_SENDER: ${{ vars.INFRA_CONTACT_FORM_SMTP_SENDER }}
          INFRA_CONTACT_FORM_SMTP_USERNAME: ${{ secrets.INFRA_CONTACT_FORM_SMTP_USERNAME }}
          INFRA_CONTACT_FORM_SMTP_PASSWORD: ${{ secrets.INFRA_CONTACT_FORM_SMTP_PASSWORD }}
          INFRA_CONTACT_FORM_RECEIVER: ${{ vars.INFRA_CONTACT_FORM_RECEIVER }}

          INFRA_AUTH_JWT_SIGNING_KEY: ${{ secrets.DEV_AUTH_JWT_SIGNING_KEY }}
          INFRA_AUTH_OPENFORT_PUBLISHABLE_KEY: ${{ secrets.DEV_AUTH_OPENFORT_PUBLISHABLE_KEY }}
          INFRA_REST_COOKIE_ENCRYPTION_SECRET_KEY: ${{ secrets.DEV_REST_COOKIE_ENCRYPTION_SECRET_KEY }}
        run: docker compose -f ${{ vars.DOCKER_COMPOSE_PATH_DEVELOP }} up -d api --force-recreate
      - name: Check status
        run: docker compose -f ${{ vars.DOCKER_COMPOSE_PATH_DEVELOP }} ps

name: Deploy to Production Environment
on:
  push:
    branches: [ "main" ]

jobs:
  build:
    name: Build docker image
    runs-on: prod-runner
    steps:
      - name: Checkout
        uses: actions/checkout@v6
      - name: Build Docker image
        run: docker build --no-cache -f ./deployment/Dockerfile -t infra-backend:prod .
      - name: Check migration tool
        run: |
          which migrate || (echo "migrate tool not found, installing..." && \
          curl -L https://github.com/golang-migrate/migrate/releases/download/v4.19.1/migrate.linux-amd64.tar.gz | tar xvz && \
          mv migrate /usr/local/bin/migrate)
      - name: Run database migrations
        env:
          INFRA_POSTGRES_DATABASE: ${{ secrets.POSTGRES_DATABASE }}
          INFRA_POSTGRES_USERNAME: ${{ secrets.POSTGRES_USER }}
          INFRA_POSTGRES_PASSWORD: ${{ secrets.POSTGRES_PASSWORD }}
        run: |
          DATABASE_URL="postgres://${INFRA_POSTGRES_USERNAME}:${INFRA_POSTGRES_PASSWORD}@localhost:5432/${INFRA_POSTGRES_DATABASE}?sslmode=disable&timezone=UTC" make migration-up

  deploy:
    name: Deploy to Production Server
    runs-on: prod-runner
    needs: build
    steps:
      - name: Deploy with Docker Compose
        env:
          INFRA_ENVIRONMENT: production
          INFRA_POSTGRES_USERNAME: ${{ secrets.POSTGRES_USER }}
          INFRA_POSTGRES_DATABASE: ${{ secrets.POSTGRES_DATABASE }}
          INFRA_POSTGRES_PASSWORD: ${{ secrets.POSTGRES_PASSWORD }}

          INFRA_REST_RECAPTCHA_GOOGLE_SECRET: ${{ secrets.GOOGLE_RECAPTCHA_SECRET }}

          INFRA_CONTACT_FORM_SMTP_HOST: ${{ vars.INFRA_CONTACT_FORM_SMTP_HOST }}
          INFRA_CONTACT_FORM_SMTP_PORT: ${{ vars.INFRA_CONTACT_FORM_SMTP_PORT }}
          INFRA_CONTACT_FORM_SMTP_SENDER: ${{ vars.INFRA_CONTACT_FORM_SMTP_SENDER }}
          INFRA_CONTACT_FORM_SMTP_USERNAME: ${{ secrets.INFRA_CONTACT_FORM_SMTP_USERNAME }}
          INFRA_CONTACT_FORM_SMTP_PASSWORD: ${{ secrets.INFRA_CONTACT_FORM_SMTP_PASSWORD }}
          INFRA_CONTACT_FORM_RECEIVER: ${{ vars.INFRA_CONTACT_FORM_RECEIVER }}

          INFRA_AUTH_JWT_SIGNING_KEY: ${{ secrets.AUTH_JWT_SIGNING_KEY }}
          INFRA_AUTH_OPENFORT_PUBLISHABLE_KEY: ${{ secrets.AUTH_OPENFORT_PUBLISHABLE_KEY }}
          INFRA_REST_COOKIE_ENCRYPTION_SECRET_KEY: ${{ secrets.REST_COOKIE_ENCRYPTION_SECRET_KEY }}
        run: docker compose -f ${{ vars.DOCKER_COMPOSE_PATH_PRODUCTION }} up -d api --force-recreate
      - name: Check status
        run: docker compose -f ${{ vars.DOCKER_COMPOSE_PATH_PRODUCTION }} ps

