'use client';

import type { User } from '@openfort/openfort-js';
import { RecoveryMethod, useSignOut, useUser } from '@openfort/react';
import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
import {
  checkOpenfortUser,
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  QualificationQuestionnaire,
  type QualificationSubmission,
} from './qualification-questionnaire';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'needs_onboarding'
  | 'creating_wallet'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  retry: () => void;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return 'Failed to initialize your session.';
}

function clearOnboardingDraft() {
  if (typeof window !== 'undefined') {
    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
  }
}

function normalizeRole(role: QualificationSubmission['role']) {
  if (role === 'client') {
    return 'project_owner';
  }

  if (role === 'dao') {
    return 'governance';
  }

  return role;
}

export function AuthSessionProvider({ children }: { children: ReactNode }) {
  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
  const { signOut } = useSignOut();
  const { create, wallets } = useEthereumEmbeddedWallet();
  const openfortUserId = user?.id ?? null;
  const [status, setStatus] = useState<AppSessionStatus>('idle');
  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
    null
  );
  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
    useState<string | null>(null);
  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
    accessToken: string;
    user: BackendMeResponse;
  } | null>(null);
  const previousAuthState = useRef(false);

  const clearSession = useCallback(() => {
    setBackendAccessToken(null);
    setBackendUser(null);
    setPendingOnboardingAccessToken(null);
    setPendingWalletCreation(null);
    setError(null);
    clearOnboardingDraft();
  }, []);

  const finalizeAuthenticatedSession = useCallback(
    (accessToken: string, currentUser: BackendMeResponse) => {
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      setError(null);
      clearOnboardingDraft();
      setStatus('authenticated');
    },
    []
  );

  const createWalletIfNeeded = useCallback(
    async (accessToken: string, currentUser: BackendMeResponse) => {
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingWalletCreation({ accessToken, user: currentUser });

      if (wallets.length > 0) {
        finalizeAuthenticatedSession(accessToken, currentUser);
        return;
      }

      setStatus('creating_wallet');

      try {
        await create({
          recoveryMethod: RecoveryMethod.AUTOMATIC,
        });
        finalizeAuthenticatedSession(accessToken, currentUser);
      } catch (walletError) {
        setError(getErrorMessage(walletError));
        setStatus('error');
      }
    },
    [create, finalizeAuthenticatedSession, wallets.length]
  );

  const bootstrapSession = useCallback(async () => {
    if (!openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    setStatus('loading');
    setError(null);

    try {
      const refreshedSession = await refreshBackendSession().catch(() => null);

      if (refreshedSession) {
        const me = await getBackendMe(refreshedSession.access_token);
        finalizeAuthenticatedSession(refreshedSession.access_token, me);
        return;
      }

      const openfortAccessToken = await getAccessToken();

      if (!openfortAccessToken) {
        throw new Error('Openfort access token is unavailable.');
      }

      const checkResponse = await checkOpenfortUser(openfortAccessToken);

      if (!checkResponse.exists) {
        setPendingOnboardingAccessToken(openfortAccessToken);
        setStatus('needs_onboarding');
        return;
      }

      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
      const me = await getBackendMe(loginResponse.access_token);

      finalizeAuthenticatedSession(loginResponse.access_token, me);
    } catch (sessionError) {
      clearSession();
      setError(getErrorMessage(sessionError));
      setStatus('error');
    }
  }, [clearSession, finalizeAuthenticatedSession, getAccessToken, openfortUserId]);

  const completeOnboarding = useCallback(
    async ({ role, type, organizationName }: QualificationSubmission) => {
      if (!pendingOnboardingAccessToken) {
        setError('Openfort access token is unavailable.');
        setStatus('error');
        return;
      }

      setStatus('loading');
      setError(null);

      try {
        const loginResponse = await exchangeOpenfortSession(
          pendingOnboardingAccessToken,
          {
            role: normalizeRole(role),
            type,
            organization_name:
              type === 'organization' ? organizationName?.trim() : undefined,
          }
        );
        const me = await getBackendMe(loginResponse.access_token);

        await createWalletIfNeeded(loginResponse.access_token, me);
      } catch (sessionError) {
        setError(getErrorMessage(sessionError));
        setStatus('needs_onboarding');
      }
    },
    [createWalletIfNeeded, pendingOnboardingAccessToken]
  );

  const abandonOnboarding = useCallback(async () => {
    clearSession();
    setStatus('loading');

    await Promise.allSettled([
      logoutBackendSession(),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [clearSession, signOut]);

  const retry = useCallback(() => {
    if (pendingWalletCreation) {
      void createWalletIfNeeded(
        pendingWalletCreation.accessToken,
        pendingWalletCreation.user
      );
      return;
    }

    setRetryCount((count) => count + 1);
  }, [createWalletIfNeeded, pendingWalletCreation]);

  useEffect(() => {
    if (isLoading) {
      setStatus((currentStatus) =>
        currentStatus === 'authenticated' ||
          currentStatus === 'needs_onboarding'
          ? currentStatus
          : 'loading'
      );
      return;
    }

    if (!isAuthenticated || !openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    void bootstrapSession();
  }, [
    bootstrapSession,
    clearSession,
    isAuthenticated,
    isLoading,
    openfortUserId,
    retryCount,
  ]);

  useEffect(() => {
    const signedOut =
      previousAuthState.current && !isLoading && !isAuthenticated;

    previousAuthState.current = isAuthenticated;

    if (!signedOut) {
      return;
    }

    clearSession();
    setStatus('unauthenticated');
    void logoutBackendSession().catch(() => undefined);
  }, [clearSession, isAuthenticated, isLoading]);

  const value = useMemo<AuthSessionContextValue>(
    () => ({
      status,
      backendAccessToken,
      backendUser,
      openfortUser: user,
      isOpenfortLoading: isLoading,
      isOpenfortAuthenticated: isAuthenticated,
      error,
      retry,
    }),
    [
      status,
      backendAccessToken,
      backendUser,
      user,
      isLoading,
      isAuthenticated,
      error,
      retry,
    ]
  );

  return (
    <AuthSessionContext.Provider value={value}>
      {children}
      <QualificationQuestionnaire
        isOpen={status === 'needs_onboarding'}
        openfortUser={user}
        submitError={error}
        isSubmitting={status === 'loading'}
        onClose={() => {
          void abandonOnboarding();
        }}
        onSubmit={completeOnboarding}
        onDisqualifiedSuccess={abandonOnboarding}
      />
    </AuthSessionContext.Provider>
  );
}

export function useAuthSession() {
  const context = useContext(AuthSessionContext);

  if (!context) {
    throw new Error(
      'useAuthSession must be used within an AuthSessionProvider.'
    );
  }

  return context;
}

'use client';

import type { User } from '@openfort/openfort-js';
import { Modal } from '@/components/ui/modal';
import { CustomButton } from '@/components/ui/custom-button';
import { CustomCheckbox } from '@/components/ui/custom-checkbox';
import { FormInput } from '@/components/ui/form-input';
import { NonResidentForm } from './non-resident-form';
import { useEffect, useMemo, useState } from 'react';

type Step = 1 | 2 | 3 | 'non_resident';
type UserType = 'individual' | 'organization';

export type QualificationRole = 'client' | 'investor' | 'contractor' | 'dao';

export interface QualificationSubmission {
  role: QualificationRole;
  type: UserType;
  organizationName?: string;
}

interface QualificationQuestionnaireProps {
  isOpen: boolean;
  openfortUser: User | null;
  submitError: string | null;
  isSubmitting: boolean;
  onClose: () => void;
  onSubmit: (submission: QualificationSubmission) => Promise<void>;
  onDisqualifiedSuccess: () => Promise<void>;
}

interface QuestionnaireDraft {
  step: Step;
  role: QualificationRole | null;
  type: UserType | null;
  organizationName: string;
  individualConfirmations: {
    ukResident: boolean;
    niNumber: boolean;
    over18: boolean;
  };
  organizationConfirmations: {
    ukBased: boolean;
    companyHouse: boolean;
    active: boolean;
  };
}

const DRAFT_KEY = 'infrafund:onboarding-draft';

const defaultDraft: QuestionnaireDraft = {
  step: 1,
  role: null,
  type: null,
  organizationName: '',
  individualConfirmations: {
    ukResident: true,
    niNumber: true,
    over18: true,
  },
  organizationConfirmations: {
    ukBased: true,
    companyHouse: true,
    active: true,
  },
};

const roleOptions: Array<{
  value: QualificationRole;
  title: string;
  description: string;
}> = [
  {
    value: 'client',
    title: 'Raise Funds',
    description:
      'Project owners and developers seeking capital for infrastructure projects.',
  },
  {
    value: 'investor',
    title: 'Invest in Assets',
    description:
      'Investors looking to discover and fund high-impact infrastructure opportunities.',
  },
  {
    value: 'contractor',
    title: 'Manage Construction',
    description:
      'EPCs and contractors supporting delivery and milestone execution.',
  },
  {
    value: 'dao',
    title: 'Join the DAO',
    description:
      'Governance participants helping guide protocol and treasury decisions.',
  },
];

function readDraft(): QuestionnaireDraft {
  if (typeof window === 'undefined') {
    return defaultDraft;
  }

  try {
    const raw = window.sessionStorage.getItem(DRAFT_KEY);

    if (!raw) {
      return defaultDraft;
    }

    return {
      ...defaultDraft,
      ...(JSON.parse(raw) as Partial<QuestionnaireDraft>),
    };
  } catch {
    return defaultDraft;
  }
}

function clearDraft() {
  if (typeof window !== 'undefined') {
    window.sessionStorage.removeItem(DRAFT_KEY);
  }
}

export function QualificationQuestionnaire({
  isOpen,
  openfortUser,
  submitError,
  isSubmitting,
  onClose,
  onSubmit,
  onDisqualifiedSuccess,
}: QualificationQuestionnaireProps) {
  const [draft, setDraft] = useState<QuestionnaireDraft>(defaultDraft);
  const [localError, setLocalError] = useState<string | null>(null);

  useEffect(() => {
    if (!isOpen) {
      setDraft(defaultDraft);
      setLocalError(null);
      return;
    }

    setDraft(readDraft());
    setLocalError(null);
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen || typeof window === 'undefined') {
      return;
    }

    window.sessionStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
  }, [draft, isOpen]);

  const currentError = submitError || localError;
  const isOrganizationReady =
    draft.type === 'organization' ? Boolean(draft.organizationName.trim()) : true;

  const activeStepTitle = useMemo(() => {
    if (draft.step === 'non_resident') {
      return 'Contact Form';
    }

    return 'Qualification';
  }, [draft.step]);

  function updateDraft(partial: Partial<QuestionnaireDraft>) {
    setDraft((currentDraft) => ({
      ...currentDraft,
      ...partial,
    }));
  }

  function updateIndividualConfirmation(
    key: keyof QuestionnaireDraft['individualConfirmations']
  ) {
    setLocalError(null);
    setDraft((currentDraft) => ({
      ...currentDraft,
      individualConfirmations: {
        ...currentDraft.individualConfirmations,
        [key]: !currentDraft.individualConfirmations[key],
      },
    }));
  }

  function updateOrganizationConfirmation(
    key: keyof QuestionnaireDraft['organizationConfirmations']
  ) {
    setLocalError(null);
    setDraft((currentDraft) => ({
      ...currentDraft,
      organizationConfirmations: {
        ...currentDraft.organizationConfirmations,
        [key]: !currentDraft.organizationConfirmations[key],
      },
    }));
  }

  async function handleQualificationSubmit() {
    if (!draft.role || !draft.type) {
      return;
    }

    if (draft.type === 'individual') {
      if (
        !draft.individualConfirmations.ukResident ||
        !draft.individualConfirmations.niNumber
      ) {
        updateDraft({ step: 'non_resident' });
        return;
      }

      if (!draft.individualConfirmations.over18) {
        setLocalError(
          'We do not provide services to individuals under 18 years old.'
        );
        return;
      }
    } else {
      if (!draft.organizationName.trim()) {
        setLocalError('Company name is required for organization onboarding.');
        return;
      }

      if (
        !draft.organizationConfirmations.ukBased ||
        !draft.organizationConfirmations.companyHouse ||
        !draft.organizationConfirmations.active
      ) {
        updateDraft({ step: 'non_resident' });
        return;
      }
    }

    setLocalError(null);

    await onSubmit({
      role: draft.role,
      type: draft.type,
      organizationName:
        draft.type === 'organization' ? draft.organizationName.trim() : undefined,
    });
  }

  async function handleDisqualifiedSuccess() {
    clearDraft();
    await onDisqualifiedSuccess();
  }

  if (!isOpen) {
    return null;
  }

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      ModalTitle={activeStepTitle}
      width="42rem"
    >
      {draft.step === 'non_resident' && draft.type ? (
        <NonResidentForm
          type={draft.type}
          openfortUser={openfortUser}
          onBack={() => updateDraft({ step: 3 })}
          onSuccess={handleDisqualifiedSuccess}
        />
      ) : (
        <div className="flex w-full flex-col gap-8 py-2 text-left text-white">
          {draft.step === 1 ? (
            <>
              <div className="space-y-2">
                <p className="text-sm uppercase tracking-[0.2em] text-[#00FF87]">
                  Let&apos;s get started
                </p>
                <h3 className="text-3xl font-semibold">
                  What brings you to InfraFund?
                </h3>
              </div>

              <div className="grid gap-3">
                {roleOptions.map((option) => {
                  const isSelected = draft.role === option.value;

                  return (
                    <button
                      key={option.value}
                      type="button"
                      onClick={() => {
                        setLocalError(null);
                        updateDraft({ role: option.value });
                      }}
                      className={`rounded-2xl border px-5 py-4 text-left transition ${
                        isSelected
                          ? 'border-[#00FF87] bg-[#111827]'
                          : 'border-[#263247] bg-[#0F1722]'
                      }`}
                    >
                      <div className="space-y-1">
                        <div className="text-lg font-semibold">{option.title}</div>
                        <div className="text-sm text-[#C7CAD5]">
                          {option.description}
                        </div>
                      </div>
                    </button>
                  );
                })}
              </div>

              <CustomButton
                className="w-full px-6 py-3 text-base"
                disabled={!draft.role}
                onClick={() => updateDraft({ step: 2 })}
              >
                Continue
              </CustomButton>
            </>
          ) : null}

          {draft.step === 2 ? (
            <>
              <div className="space-y-2">
                <h3 className="text-3xl font-semibold">
                  Are you an Individual or Organization?
                </h3>
                <p className="text-sm text-[#C7CAD5]">
                  We use this to route you through the right qualification checks.
                </p>
              </div>

              <div className="grid gap-4 md:grid-cols-2">
                {(['individual', 'organization'] as const).map((option) => {
                  const isSelected = draft.type === option;

                  return (
                    <button
                      key={option}
                      type="button"
                      onClick={() => {
                        setLocalError(null);
                        updateDraft({ type: option });
                      }}
                      className={`rounded-2xl border px-5 py-8 text-left transition ${
                        isSelected
                          ? 'border-[#00FF87] bg-[#111827]'
                          : 'border-[#263247] bg-[#0F1722]'
                      }`}
                    >
                      <div className="text-xl font-semibold capitalize">
                        {option}
                      </div>
                    </button>
                  );
                })}
              </div>

              {draft.type === 'organization' ? (
                <FormInput
                  label="Company Name"
                  placeholder="Company Name"
                  value={draft.organizationName}
                  onChange={(event) =>
                    updateDraft({ organizationName: event.target.value })
                  }
                />
              ) : null}

              {currentError ? (
                <p className="text-sm text-red-400">{currentError}</p>
              ) : null}

              <div className="flex w-full flex-col gap-3 sm:flex-row">
                <CustomButton
                  variant="outlined"
                  className="w-full px-6 py-3 text-base sm:w-1/2"
                  onClick={() => updateDraft({ step: 1 })}
                >
                  Back
                </CustomButton>
                <CustomButton
                  className="w-full px-6 py-3 text-base sm:w-1/2"
                  disabled={!draft.type || !isOrganizationReady}
                  onClick={() => updateDraft({ step: 3 })}
                >
                  Continue
                </CustomButton>
              </div>
            </>
          ) : null}

          {draft.step === 3 ? (
            <>
              <div className="space-y-2">
                <h3 className="text-3xl font-semibold">
                  First, please confirm the following.
                </h3>
                <p className="text-sm text-[#C7CAD5]">
                  All responses must remain selected to continue.
                </p>
              </div>

              <div className="space-y-4">
                {draft.type === 'individual' ? (
                  <>
                    <button
                      type="button"
                      onClick={() => updateIndividualConfirmation('ukResident')}
                      className="flex w-full items-start gap-4 rounded-2xl border border-[#263247] bg-[#0F1722] p-4 text-left"
                    >
                      <CustomCheckbox
                        checked={draft.individualConfirmations.ukResident}
                        onToggle={() => undefined}
                        className="mt-1"
                      />
                      <span>I am currently a UK resident.</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => updateIndividualConfirmation('niNumber')}
                      className="flex w-full items-start gap-4 rounded-2xl border border-[#263247] bg-[#0F1722] p-4 text-left"
                    >
                      <CustomCheckbox
                        checked={draft.individualConfirmations.niNumber}
                        onToggle={() => undefined}
                        className="mt-1"
                      />
                      <span>I have a valid UK national insurance number.</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => updateIndividualConfirmation('over18')}
                      className="flex w-full items-start gap-4 rounded-2xl border border-[#263247] bg-[#0F1722] p-4 text-left"
                    >
                      <CustomCheckbox
                        checked={draft.individualConfirmations.over18}
                        onToggle={() => undefined}
                        className="mt-1"
                      />
                      <span>I am at least 18 years old.</span>
                    </button>
                  </>
                ) : (
                  <>
                    <button
                      type="button"
                      onClick={() => updateOrganizationConfirmation('ukBased')}
                      className="flex w-full items-start gap-4 rounded-2xl border border-[#263247] bg-[#0F1722] p-4 text-left"
                    >
                      <CustomCheckbox
                        checked={draft.organizationConfirmations.ukBased}
                        onToggle={() => undefined}
                        className="mt-1"
                      />
                      <span>Our company is based in the UK.</span>
                    </button>
                    <button
                      type="button"
                      onClick={() =>
                        updateOrganizationConfirmation('companyHouse')
                      }
                      className="flex w-full items-start gap-4 rounded-2xl border border-[#263247] bg-[#0F1722] p-4 text-left"
                    >
                      <CustomCheckbox
                        checked={draft.organizationConfirmations.companyHouse}
                        onToggle={() => undefined}
                        className="mt-1"
                      />
                      <span>We have a valid UK Companies House number.</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => updateOrganizationConfirmation('active')}
                      className="flex w-full items-start gap-4 rounded-2xl border border-[#263247] bg-[#0F1722] p-4 text-left"
                    >
                      <CustomCheckbox
                        checked={draft.organizationConfirmations.active}
                        onToggle={() => undefined}
                        className="mt-1"
                      />
                      <span>Our company is currently active.</span>
                    </button>
                  </>
                )}
              </div>

              {currentError ? (
                <p className="text-sm text-red-400">{currentError}</p>
              ) : null}

              <div className="flex w-full flex-col gap-3 sm:flex-row">
                <CustomButton
                  variant="outlined"
                  className="w-full px-6 py-3 text-base sm:w-1/2"
                  onClick={() => updateDraft({ step: 2 })}
                  disabled={isSubmitting}
                >
                  Back
                </CustomButton>
                <CustomButton
                  className="w-full px-6 py-3 text-base sm:w-1/2"
                  onClick={handleQualificationSubmit}
                  disabled={isSubmitting}
                >
                  {isSubmitting ? 'Continuing...' : 'Continue'}
                </CustomButton>
              </div>
            </>
          ) : null}
        </div>
      )}
    </Modal>
  );
}

'use client';

import {
  getCountries,
  submitNonResidentCompany,
  submitNonResidentIndividual,
  type CountryOption,
} from '@/lib/backend-auth-client';
import { CustomButton } from '@/components/ui/custom-button';
import { Dropdown } from '@/components/ui/dropdown';
import { FormInput } from '@/components/ui/form-input';
import { getRecaptchaToken } from '@/utils/recaptcha';
import { useEffect, useMemo, useState } from 'react';

interface OpenfortUserDetails {
  email?: string | null;
  name?: string | null;
}

interface NonResidentFormProps {
  type: 'individual' | 'organization';
  openfortUser?: OpenfortUserDetails | null;
  onBack: () => void;
  onSuccess: () => void | Promise<void>;
}

function splitName(fullName?: string | null) {
  const parts = (fullName || '')
    .trim()
    .split(/\s+/)
    .filter(Boolean);

  if (parts.length === 0) {
    return { firstName: '', lastName: '' };
  }

  if (parts.length === 1) {
    return { firstName: parts[0], lastName: '' };
  }

  return {
    firstName: parts[0],
    lastName: parts.slice(1).join(' '),
  };
}

export function NonResidentForm({
  type,
  openfortUser,
  onBack,
  onSuccess,
}: NonResidentFormProps) {
  const defaultName = useMemo(() => splitName(openfortUser?.name), [openfortUser]);
  const [countries, setCountries] = useState<CountryOption[]>([]);
  const [isLoadingCountries, setIsLoadingCountries] = useState(true);
  const [countryError, setCountryError] = useState<string | null>(null);
  const [countryId, setCountryId] = useState('');
  const [email, setEmail] = useState(openfortUser?.email || '');
  const [firstName, setFirstName] = useState(defaultName.firstName);
  const [lastName, setLastName] = useState(defaultName.lastName);
  const [contactFullName, setContactFullName] = useState(openfortUser?.name || '');
  const [companyName, setCompanyName] = useState('');
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);

  useEffect(() => {
    setEmail(openfortUser?.email || '');
    setFirstName(defaultName.firstName);
    setLastName(defaultName.lastName);
    setContactFullName(openfortUser?.name || '');
  }, [defaultName.firstName, defaultName.lastName, openfortUser]);

  useEffect(() => {
    let isMounted = true;

    async function loadCountries() {
      setIsLoadingCountries(true);
      setCountryError(null);

      try {
        const items = await getCountries();

        if (!isMounted) {
          return;
        }

        setCountries(items);
      } catch (error) {
        if (!isMounted) {
          return;
        }

        setCountryError(
          error instanceof Error
            ? error.message
            : 'Unable to load countries right now.'
        );
      } finally {
        if (isMounted) {
          setIsLoadingCountries(false);
        }
      }
    }

    void loadCountries();

    return () => {
      isMounted = false;
    };
  }, []);

  const disclaimer =
    type === 'individual'
      ? 'Unfortunately, at this point in time, we cannot accept investments from people who are not UK residents or do not have a valid UK national insurance number.'
      : 'Unfortunately, at this point in time, we cannot accept investments from organizations that are not based in the UK or do not meet the current requirements.';

  const isValid =
    type === 'individual'
      ? Boolean(
          firstName.trim() &&
            lastName.trim() &&
            email.trim() &&
            countryId &&
            !isSubmitting
        )
      : Boolean(
          contactFullName.trim() &&
            companyName.trim() &&
            email.trim() &&
            countryId &&
            !isSubmitting
        );

  async function handleSubmit() {
    if (!isValid) {
      return;
    }

    setSubmitError(null);
    setIsSubmitting(true);

    try {
      const captchaToken = await getRecaptchaToken('non_resident_waitlist');

      if (type === 'individual') {
        await submitNonResidentIndividual(
          {
            first_name: firstName.trim(),
            last_name: lastName.trim(),
            email: email.trim().toLowerCase(),
            country_id: Number(countryId),
          },
          captchaToken
        );
      } else {
        const contactName = splitName(contactFullName);

        await submitNonResidentCompany(
          {
            first_name: contactName.firstName.trim(),
            last_name: contactName.lastName.trim(),
            company_name: companyName.trim(),
            email: email.trim().toLowerCase(),
            country_id: Number(countryId),
          },
          captchaToken
        );
      }

      setIsSubmitted(true);
      await new Promise((resolve) => setTimeout(resolve, 1200));
      await onSuccess();
    } catch (error) {
      setSubmitError(
        error instanceof Error ? error.message : 'Unable to submit the form.'
      );
    } finally {
      setIsSubmitting(false);
    }
  }

  if (isSubmitted) {
    return (
      <div className="flex w-full flex-col gap-6 py-4 text-left text-white">
        <div className="space-y-2">
          <h3 className="text-2xl font-semibold">Thank you</h3>
          <p className="text-sm text-[#C7CAD5]">
            We&apos;ll keep your details on file and reach out when InfraFund is
            available in your market.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex w-full flex-col gap-6 py-2 text-left text-white">
      <div className="space-y-2">
        <h3 className="text-2xl font-semibold">Stay in touch</h3>
        <p className="text-sm text-[#C7CAD5]">{disclaimer}</p>
        <p className="text-sm text-[#C7CAD5]">
          If you&apos;d like to hear from us when eligibility expands, leave
          your details below.
        </p>
      </div>

      <div className="grid w-full gap-4 md:grid-cols-2">
        {type === 'individual' ? (
          <>
            <FormInput
              label="First Name"
              placeholder="First Name"
              value={firstName}
              onChange={(event) => setFirstName(event.target.value)}
            />
            <FormInput
              label="Last Name"
              placeholder="Last Name"
              value={lastName}
              onChange={(event) => setLastName(event.target.value)}
            />
          </>
        ) : (
          <>
            <FormInput
              label="Contact Full Name"
              placeholder="Contact Full Name"
              value={contactFullName}
              onChange={(event) => setContactFullName(event.target.value)}
              className="md:col-span-2"
            />
            <FormInput
              label="Company Name"
              placeholder="Company Name"
              value={companyName}
              onChange={(event) => setCompanyName(event.target.value)}
              className="md:col-span-2"
            />
          </>
        )}

        <Dropdown
          label="Country"
          options={countries.map((country) => ({
            key: String(country.id),
            label: country.name,
            value: String(country.id),
          }))}
          value={countryId}
          onChange={(value) => setCountryId(value)}
          placeholder={
            isLoadingCountries ? 'Loading countries...' : 'Select a country'
          }
          className="md:col-span-2"
        />

        <FormInput
          label="Email"
          placeholder="Email"
          type="email"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          className="md:col-span-2"
        />
      </div>

      {countryError ? (
        <p className="text-sm text-red-400">{countryError}</p>
      ) : null}
      {submitError ? <p className="text-sm text-red-400">{submitError}</p> : null}

      <div className="flex w-full flex-col gap-3 sm:flex-row">
        <CustomButton
          variant="outlined"
          className="w-full px-6 py-3 text-base sm:w-1/2"
          onClick={onBack}
          disabled={isSubmitting}
        >
          Back
        </CustomButton>
        <CustomButton
          className="w-full px-6 py-3 text-base sm:w-1/2"
          onClick={handleSubmit}
          disabled={!isValid || Boolean(countryError) || isLoadingCountries}
        >
          {isSubmitting ? 'Submitting...' : 'Notify me'}
        </CustomButton>
      </div>
    </div>
  );
}

'use client';
import type React from 'react';
import AppSidebar from './sidebar';
import Header from './header';
import { usePathname, useRouter } from 'next/navigation';
import { useEffect } from 'react';
import { AuthErrorState, AuthLoadingState } from './auth/auth-state';
import { useAuthSession } from './auth/auth-session-provider';

interface MainLayoutProps {
  children: React.ReactNode;
}

export function MainLayout({ children }: MainLayoutProps) {
  const pathname = usePathname();
  const router = useRouter();
  const isPublicRoute = pathname === '/' || pathname === '/login';
  const { status, error, retry, isOpenfortAuthenticated, isOpenfortLoading } =
    useAuthSession();

  useEffect(() => {
    if (isOpenfortLoading || !pathname) {
      return;
    }

    if (isPublicRoute) {
      if (status === 'authenticated') {
        router.replace('/home');
      }

      return;
    }

    if (status !== 'authenticated') {
      router.replace('/');
    }
  }, [
    isOpenfortLoading,
    isPublicRoute,
    pathname,
    router,
    status,
  ]);

  const showPublicAuthLoading =
    isOpenfortLoading ||
    (isOpenfortAuthenticated &&
      (status === 'idle' || status === 'loading' || status === 'creating_wallet'));
  const showPrivateAuthLoading =
    isOpenfortLoading ||
    status === 'idle' ||
    status === 'loading' ||
    status === 'creating_wallet';

  return (
    <div className="relative min-h-screen overflow-hidden bg-[#0C0C0D]">
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute -top-32 -right-32 opacity-50 w-[662px] h-[662px] rounded-full blur-3xl bg-[#1A2A4AAD]" />
        <div className="absolute -bottom-44 -left-32 opacity-50 w-[662px] h-[662px] rounded-full blur-3xl bg-[#1A2A4AAD]" />
      </div>

      {isPublicRoute ? (
        <div className="relative z-[999] flex items-center justify-center min-h-screen p-4">
          {showPublicAuthLoading ? (
            <AuthLoadingState message="Checking your Openfort session..." />
          ) : status === 'error' ? (
            <AuthErrorState
              message={error || 'Unable to continue.'}
              onRetry={retry}
            />
          ) : (
            children
          )}
        </div>
      ) : (
        <div className="relative z-[999] flex min-h-screen items-center justify-center p-4 md:p-8 lg:p-12">
          {showPrivateAuthLoading ? (
            <AuthLoadingState message="Restoring your InfraFund session..." />
          ) : status === 'error' ? (
            <AuthErrorState
              message={error || 'Unable to continue.'}
              onRetry={retry}
            />
          ) : (
            <div className="relative z-[999] flex p-4 md:p-8 lg:p-12 gap-4 md:gap-8 lg:gap-12 min-h-screen w-full">
              <div className="h-full -mt-3.5">
                <AppSidebar />
              </div>
              <div className="flex-1">
                <div className="flex flex-col h-fit px-12 gap-12">
                  <Header />
                  <main className="flex-1 backdrop-blur-sm rounded-lg">
                    {children}
                  </main>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

interface BackendLoginResponse {
  user_id: string;
  access_token: string;
  expires_at: string;
}

interface BackendCheckResponse {
  exists: boolean;
}

interface BackendCountriesResponse {
  items: BackendCountryRecord[];
}

interface BackendCountryRecord {
  ID?: number;
  id?: number;
  Name?: string;
  name?: string;
  Iso?: string;
  iso?: string;
  Iso3?: string;
  iso3?: string;
  Code?: number;
  code?: number;
  PhoneCode?: number;
  phone_code?: number;
}

export interface CountryOption {
  id: number;
  name: string;
  iso?: string;
  iso3?: string;
  code?: number;
  phoneCode?: number;
}

export interface OpenfortExchangePayload {
  first_name?: string;
  last_name?: string;
  organization_name?: string;
  phone_number?: string;
  email?: string;
  type?: 'individual' | 'organization';
  role?: string;
}

export interface NonResidentIndividualPayload {
  first_name: string;
  last_name: string;
  email: string;
  country_id: number;
}

export interface NonResidentCompanyPayload {
  first_name: string;
  last_name: string;
  company_name: string;
  email: string;
  country_id: number;
}

export interface BackendMeResponse {
  user_id: string;
  openfort_user_id: string;
  email: string | null;
  first_name: string | null;
  last_name: string | null;
  company_name: string | null;
  phone_number: string | null;
  type: string;
  role: string;
  status: string;
  kyc_verified: boolean;
  kyb_verified: boolean;
}

interface SuccessResponse<T> {
  code: string;
  data: T;
}

interface ErrorResponse {
  message?: string;
  detail?: string;
}

function getApiBaseUrl() {
  return (
    process.env.NEXT_PUBLIC_API_BASE_URL ??
    process.env.NEXT_PUBLIC_BASE_URL ??
    ''
  ).replace(/\/+$/, '');
}

function buildUrl(path: string) {
  const normalizedPath = path.replace(/^\/+/, '');
  const baseUrl = getApiBaseUrl();

  return baseUrl ? `${baseUrl}/${normalizedPath}` : `/v1/${normalizedPath}`;
}

async function request<T>(
  path: string,
  init: RequestInit & { accessToken?: string } = {}
) {
  const headers = new Headers(init.headers);

  if (init.body && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  if (init.accessToken) {
    headers.set('Authorization', `Bearer ${init.accessToken}`);
  }

  const response = await fetch(buildUrl(path), {
    ...init,
    headers,
    credentials: 'include',
  });

  if (!response.ok) {
    let message = 'Request failed';

    try {
      const errorBody = (await response.json()) as ErrorResponse;
      message = errorBody.message || errorBody.detail || message;
    } catch {}

    throw new Error(message);
  }

  if (response.status === 204) {
    return null as T;
  }

  const body = (await response.json()) as SuccessResponse<T>;
  return body.data;
}

function normalizeCountry(country: BackendCountryRecord): CountryOption {
  return {
    id: Number(country.ID ?? country.id ?? 0),
    name: String(country.Name ?? country.name ?? ''),
    iso:
      typeof country.Iso === 'string'
        ? country.Iso
        : typeof country.iso === 'string'
          ? country.iso
          : undefined,
    iso3:
      typeof country.Iso3 === 'string'
        ? country.Iso3
        : typeof country.iso3 === 'string'
          ? country.iso3
          : undefined,
    code:
      typeof country.Code === 'number'
        ? country.Code
        : typeof country.code === 'number'
          ? country.code
          : undefined,
    phoneCode:
      typeof country.PhoneCode === 'number'
        ? country.PhoneCode
        : typeof country.phone_code === 'number'
          ? country.phone_code
          : undefined,
  };
}

export async function checkOpenfortUser(openfortAccessToken: string) {
  return request<BackendCheckResponse>('auth/openfort/check', {
    method: 'GET',
    accessToken: openfortAccessToken,
  });
}

export async function exchangeOpenfortSession(
  openfortAccessToken: string,
  body: OpenfortExchangePayload = {}
) {
  return request<BackendLoginResponse>('auth/openfort/exchange', {
    method: 'POST',
    accessToken: openfortAccessToken,
    body: JSON.stringify(body),
  });
}

export async function refreshBackendSession() {
  return request<BackendLoginResponse>('auth/refresh', {
    method: 'POST',
  });
}

export async function getBackendMe(accessToken: string) {
  return request<BackendMeResponse>('me', {
    method: 'GET',
    accessToken,
  });
}

export async function getCountries() {
  const response = await request<BackendCountriesResponse>(
    'locations/countries',
    {
      method: 'GET',
    }
  );

  return response.items
    .map(normalizeCountry)
    .filter((country) => country.id > 0 && country.name);
}

export async function submitNonResidentIndividual(
  payload: NonResidentIndividualPayload,
  captchaToken: string
) {
  await request<null>('non-resident-waitlist/individual', {
    method: 'POST',
    headers: {
      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function submitNonResidentCompany(
  payload: NonResidentCompanyPayload,
  captchaToken: string
) {
  await request<null>('non-resident-waitlist/company', {
    method: 'POST',
    headers: {
      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function logoutBackendSession() {
  await request<null>('auth/logout', {
    method: 'POST',
  });
}

