'use client';

import {
  getCountries,
  submitNonResidentCompany,
  submitNonResidentIndividual,
  type CountryOption,
} from '@/lib/backend-auth-client';
import { CustomButton } from '@/components/ui/custom-button';
import { Dropdown } from '@/components/ui/dropdown';
import { FormInput } from '@/components/ui/form-input';
import { getRecaptchaToken } from '@/utils/recaptcha';
import { useEffect, useMemo, useState } from 'react';

interface OpenfortUserDetails {
  email?: string | null;
  name?: string | null;
}

interface NonResidentFormProps {
  type: 'individual' | 'organization';
  openfortUser?: OpenfortUserDetails | null;
  onBack: () => void;
  onSuccess: () => void | Promise<void>;
}

function splitName(fullName?: string | null) {
  const parts = (fullName || '').trim().split(/\s+/).filter(Boolean);

  if (parts.length === 0) {
    return { firstName: '', lastName: '' };
  }

  if (parts.length === 1) {
    return { firstName: parts[0], lastName: '' };
  }

  return {
    firstName: parts[0],
    lastName: parts.slice(1).join(' '),
  };
}

export function NonResidentForm({
  type,
  openfortUser,
  onBack,
  onSuccess,
}: NonResidentFormProps) {
  const defaultName = useMemo(
    () => splitName(openfortUser?.name),
    [openfortUser]
  );
  const [countries, setCountries] = useState<CountryOption[]>([]);
  const [isLoadingCountries, setIsLoadingCountries] = useState(true);
  const [countryError, setCountryError] = useState<string | null>(null);
  const [countryId, setCountryId] = useState('');
  const [email, setEmail] = useState(openfortUser?.email || '');
  const [firstName, setFirstName] = useState(defaultName.firstName);
  const [lastName, setLastName] = useState(defaultName.lastName);
  const [contactFullName, setContactFullName] = useState(
    openfortUser?.name || ''
  );
  const [companyName, setCompanyName] = useState('');
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSubmitted, setIsSubmitted] = useState(false);
  const contactName = useMemo(
    () => splitName(contactFullName),
    [contactFullName]
  );

  useEffect(() => {
    setEmail(openfortUser?.email || '');
    setFirstName(defaultName.firstName);
    setLastName(defaultName.lastName);
    setContactFullName(openfortUser?.name || '');
  }, [defaultName.firstName, defaultName.lastName, openfortUser]);

  useEffect(() => {
    let isMounted = true;

    async function loadCountries() {
      setIsLoadingCountries(true);
      setCountryError(null);

      try {
        const items = await getCountries();

        if (!isMounted) {
          return;
        }

        setCountries(items);
      } catch (error) {
        if (!isMounted) {
          return;
        }

        setCountryError(
          error instanceof Error
            ? error.message
            : 'Unable to load countries right now.'
        );
      } finally {
        if (isMounted) {
          setIsLoadingCountries(false);
        }
      }
    }

    void loadCountries();

    return () => {
      isMounted = false;
    };
  }, []);

  const disclaimer =
    type === 'individual'
      ? 'Unfortunately, at this point in time, we cannot accept investments from people who are not UK residents or do not have a valid UK national insurance number.'
      : 'Unfortunately, at this point in time, we cannot accept investments from organizations that are not based in the UK or do not meet the current requirements.';
  const hasFullContactName =
    type === 'organization'
      ? Boolean(contactName.firstName.trim() && contactName.lastName.trim())
      : true;

  const isValid =
    type === 'individual'
      ? Boolean(
          firstName.trim() &&
          lastName.trim() &&
          email.trim() &&
          countryId &&
          !isSubmitting
        )
      : Boolean(
          contactFullName.trim() &&
          hasFullContactName &&
          companyName.trim() &&
          email.trim() &&
          countryId &&
          !isSubmitting
        );

  async function handleSubmit() {
    if (!isValid) {
      return;
    }

    setSubmitError(null);
    setIsSubmitting(true);

    try {
      const captchaToken = await getRecaptchaToken('non_resident_waitlist');

      if (type === 'individual') {
        await submitNonResidentIndividual(
          {
            first_name: firstName.trim(),
            last_name: lastName.trim(),
            email: email.trim().toLowerCase(),
            country_id: Number(countryId),
          },
          captchaToken
        );
      } else {
        await submitNonResidentCompany(
          {
            first_name: contactName.firstName.trim(),
            last_name: contactName.lastName.trim(),
            company_name: companyName.trim(),
            email: email.trim().toLowerCase(),
            country_id: Number(countryId),
          },
          captchaToken
        );
      }

      setIsSubmitted(true);
      await new Promise((resolve) => setTimeout(resolve, 1200));
      await onSuccess();
    } catch (error) {
      setSubmitError(
        error instanceof Error ? error.message : 'Unable to submit the form.'
      );
    } finally {
      setIsSubmitting(false);
    }
  }

  if (isSubmitted) {
    return (
      <div className="flex w-full flex-col gap-6 py-4 text-left text-white">
        <div className="space-y-2">
          <h3 className="text-2xl font-semibold">Thank you</h3>
          <p className="text-sm text-[#C7CAD5]">
            We&apos;ll keep your details on file and reach out when InfraFund is
            available in your market.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex w-full flex-col gap-6 py-2 text-left text-white">
      <div className="space-y-2">
        <h3 className="text-2xl font-semibold">Stay in touch</h3>
        <p className="text-sm text-[#C7CAD5]">{disclaimer}</p>
        <p className="text-sm text-[#C7CAD5]">
          If you&apos;d like to hear from us when eligibility expands, leave
          your details below.
        </p>
      </div>

      <div className="grid w-full gap-4 md:grid-cols-2">
        {type === 'individual' ? (
          <>
            <FormInput
              label="First Name"
              placeholder="First Name"
              value={firstName}
              onChange={(event) => setFirstName(event.target.value)}
            />
            <FormInput
              label="Last Name"
              placeholder="Last Name"
              value={lastName}
              onChange={(event) => setLastName(event.target.value)}
            />
          </>
        ) : (
          <>
            <FormInput
              label="Contact Full Name"
              placeholder="Contact Full Name"
              value={contactFullName}
              onChange={(event) => setContactFullName(event.target.value)}
              className="md:col-span-2"
            />
            <FormInput
              label="Company Name"
              placeholder="Company Name"
              value={companyName}
              onChange={(event) => setCompanyName(event.target.value)}
              className="md:col-span-2"
            />
          </>
        )}

        <Dropdown
          label="Country"
          options={countries.map((country) => ({
            key: String(country.id),
            label: country.name,
            value: String(country.id),
          }))}
          value={countryId}
          onChange={(value) => setCountryId(value)}
          placeholder={
            isLoadingCountries ? 'Loading countries...' : 'Select a country'
          }
          className="md:col-span-2"
        />

        <FormInput
          label="Email"
          placeholder="Email"
          type="email"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          className="md:col-span-2"
        />
      </div>

      {countryError ? (
        <p className="text-sm text-red-400">{countryError}</p>
      ) : null}
      {submitError ? (
        <p className="text-sm text-red-400">{submitError}</p>
      ) : null}
      {type === 'organization' && !hasFullContactName ? (
        <p className="text-sm text-red-400">
          Please enter the contact&apos;s first and last name.
        </p>
      ) : null}

      <div className="flex w-full flex-col gap-3 sm:flex-row">
        <CustomButton
          variant="outlined"
          className="w-full px-6 py-3 text-base sm:w-1/2"
          onClick={onBack}
          disabled={isSubmitting}
        >
          Back
        </CustomButton>
        <CustomButton
          className="w-full px-6 py-3 text-base sm:w-1/2"
          onClick={handleSubmit}
          disabled={!isValid || Boolean(countryError) || isLoadingCountries}
        >
          {isSubmitting ? 'Submitting...' : 'Notify me'}
        </CustomButton>
      </div>
    </div>
  );
}

'use client';
import type React from 'react';
import AppSidebar from './sidebar';
import Header from './header';
import { usePathname, useRouter } from 'next/navigation';
import { useEffect } from 'react';
import { AuthErrorState, AuthLoadingState } from './auth/auth-state';
import { useAuthSession } from './auth/auth-session-provider';

interface MainLayoutProps {
  children: React.ReactNode;
}

export function MainLayout({ children }: MainLayoutProps) {
  const pathname = usePathname();
  const router = useRouter();
  const isPublicRoute = pathname === '/' || pathname === '/login';
  const { status, error, retry, isOpenfortLoading, isOpenfortAuthenticated } =
    useAuthSession();

  useEffect(() => {
    if (isOpenfortLoading || !pathname) {
      return;
    }

    if (isPublicRoute) {
      if (status === 'authenticated') {
        router.replace('/home');
      }

      return;
    }

    if (status !== 'authenticated') {
      router.replace('/');
    }
  }, [isOpenfortLoading, isPublicRoute, pathname, router, status]);

  const showPublicAuthLoading =
    isOpenfortLoading ||
    (isOpenfortAuthenticated &&
      (status === 'idle' ||
        status === 'loading' ||
        status === 'creating_wallet'));
  const showPrivateAuthLoading =
    isOpenfortLoading ||
    status === 'idle' ||
    status === 'loading' ||
    status === 'creating_wallet';

  return (
    <div className="relative min-h-screen overflow-hidden bg-[#0C0C0D]">
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute -top-32 -right-32 opacity-50 w-[662px] h-[662px] rounded-full blur-3xl bg-[#1A2A4AAD]" />
        <div className="absolute -bottom-44 -left-32 opacity-50 w-[662px] h-[662px] rounded-full blur-3xl bg-[#1A2A4AAD]" />
      </div>

      {isPublicRoute ? (
        <div className="relative z-[999] flex items-center justify-center min-h-screen p-4">
          {showPublicAuthLoading ? (
            <AuthLoadingState message="Checking your Openfort session..." />
          ) : status === 'error' ? (
            <AuthErrorState
              message={error || 'Unable to continue.'}
              onRetry={retry}
            />
          ) : (
            children
          )}
        </div>
      ) : (
        <div className="relative z-[999] flex min-h-screen items-center justify-center p-4 md:p-8 lg:p-12">
          {showPrivateAuthLoading ? (
            <AuthLoadingState message="Restoring your InfraFund session..." />
          ) : status === 'error' ? (
            <AuthErrorState
              message={error || 'Unable to continue.'}
              onRetry={retry}
            />
          ) : (
            <div className="relative z-[999] flex p-4 md:p-8 lg:p-12 gap-4 md:gap-8 lg:gap-12 min-h-screen w-full">
              <div className="h-full -mt-3.5">
                <AppSidebar />
              </div>
              <div className="flex-1">
                <div className="flex flex-col h-fit px-12 gap-12">
                  <Header />
                  <main className="flex-1 backdrop-blur-sm rounded-lg">
                    {children}
                  </main>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

